#!/bin/bash
set -uo pipefail
printf 'CONTROL_UTC ';date -u +%FT%TZ
printf 'LOAD ';cat /proc/loadavg
for d in /root/control-t82 /root/ensayo-t82;do [ ! -e "$d" ] || { echo "NOMBRE_OCUPADO $d";exit 73;};done
[ "$(mysql -N -e "SELECT COUNT(*) FROM information_schema.schemata WHERE schema_name IN ('wings_ensayo_t82','wings_ensayo')")" = 0 ] || { echo BASE_OCUPADA;exit 73;}
[ "$(mysql -N -e "SELECT COUNT(*) FROM mysql.user WHERE User='ensayo_t82'")" = 0 ] || { echo USUARIO_OCUPADO;exit 73;}
[ "$(ss -ltnH '( sport = :8099 )' | wc -l)" = 0 ] || { echo PUERTO_OCUPADO;exit 73;}
[ "$(find /tmp -maxdepth 1 -type d -name 'restaurar-wings-*' | wc -l)" = 0 ] || { echo TEMP_PREVIO;exit 73;}
h=$(date -u +%H%M);if [[ "$h" > 0259 && "$h" < 0330 ]];then echo VENTANA_RESPALDO;exit 75;fi
awk '{exit !($1<1.0)}' /proc/loadavg || { echo CARGA_ALTA;exit 75;}
[ "$(mysql -N -e 'SELECT COUNT(*) FROM wingstest.sessions WHERE last_activity BETWEEN UNIX_TIMESTAMP()-600 AND UNIX_TIMESTAMP()')" = 0 ] || { echo SESIONES_RECIENTES;exit 75;}
for log in /usr/local/apache/domlogs/test.gestionar-te.com.ar.log /usr/local/apache/domlogs/test.gestionar-te.com.ar.ssl.log;do
 [ -f "$log" ] || { echo SIN_REGISTRO_ACCESO;exit 75;}
 age=$(( $(date +%s)-$(stat -c %Y "$log") ));echo "ACCESO_EDAD_SEGUNDOS $age";[ "$age" -gt 600 ] || { echo ACTIVIDAD_RECIENTE;exit 75;}
done
mkdir -m 700 /root/control-t82
cleanup(){
 rc=$?;trap - EXIT HUP INT TERM
 echo "CONTROL_SALIDA_ORIGINAL $rc"
 python3 - <<'PYCLEAN'
import os,signal,time
from pathlib import Path
mine=os.getpid();parents={os.getppid(),mine}
for p in Path('/proc').glob('[0-9]*'):
 try:
  pid=int(p.name);cwd=os.readlink(str(p/'cwd'))
  if pid not in parents and (cwd.startswith('/root/ensayo-t82/') or cwd.startswith('/root/control-t82/')):
   os.kill(pid,signal.SIGTERM);print('PROCESO_ENSAYO_TERMINADO',pid)
 except (OSError,ValueError):pass
time.sleep(1)
PYCLEAN
 if [ -f /root/control-t82/antes-privado.json ];then python3 /root/control-t82/auditar-datos.py liveafter || rc=81;fi
 mysql -e "DROP DATABASE IF EXISTS wings_ensayo_t82;DROP DATABASE IF EXISTS wings_ensayo;DROP USER IF EXISTS 'ensayo_t82'@'localhost';" || rc=82
 for d in /root/ensayo-t82 /root/control-t82;do if [ -e "$d" ];then [ "$(realpath "$d")" = "$d" ] && [ ! -L "$d" ] && rm -rf -- "$d" || rc=83;fi;done
 echo LIMPIEZA_COMPROBADA
 for d in /root/ensayo-t82 /root/control-t82;do [ ! -e "$d" ] && echo "CARPETA_AUSENTE $d" || rc=84;done
 mysql -N -e "SELECT 'bases_residuales',COUNT(*) FROM information_schema.schemata WHERE schema_name IN ('wings_ensayo_t82','wings_ensayo');SELECT 'usuarios_residuales',COUNT(*) FROM mysql.user WHERE User='ensayo_t82';"
 printf 'PUERTO_8099_RESIDUAL ';ss -ltnH '( sport = :8099 )' | wc -l
 printf 'TEMP_RESTAURAR_RESIDUAL ';find /tmp -maxdepth 1 -type d -name 'restaurar-wings-*' | wc -l
 exit "$rc"
}
trap cleanup EXIT HUP INT TERM
mkdir -p /root/control-t82/tmp
export COMPOSER_HOME=/root/control-t82/composer-home COMPOSER_CACHE_DIR=/root/control-t82/composer-cache npm_config_cache=/root/control-t82/npm-cache RCLONE_CACHE_DIR=/root/control-t82/rclone-cache TMPDIR=/root/control-t82/tmp
printf %s  | base64 -d > /root/control-t82/auditar-datos.py
python3 /root/control-t82/auditar-datos.py baseline || exit 80
mkdir -p /root/control-t82/arma
mysqldump --single-transaction --routines --triggers wingstest > /root/control-t82/arma/wings.sql || exit 10
cp /home/wingstest/app/.env /root/control-t82/arma/env.txt || exit 11
tar -czf /root/control-t82/arma/storage.tgz -C /home/wingstest/app storage/app || exit 12
tar -czf /root/control-t82/paquete.tgz -C /root/control-t82/arma wings.sql env.txt storage.tgz || exit 13
openssl enc -aes-256-cbc -pbkdf2 -iter 200000 -salt -in /root/control-t82/paquete.tgz -out /root/control-t82/wingstest_control.tgz.enc -pass file:/root/wings-backup/clave || exit 14
BACKUP=/root/control-t82/wingstest_control.tgz.enc
echo PAQUETE_PRUEBA_PROPIO_CREADO

mkdir -p /root/control-t82/extraido
openssl enc -d -aes-256-cbc -pbkdf2 -iter 200000 -in "$BACKUP" -out /root/control-t82/extraido/paquete.tgz -pass file:/root/wings-backup/clave || exit 20
tar -xzf /root/control-t82/extraido/paquete.tgz -C /root/control-t82/extraido || exit 21
PASS=$(openssl rand -hex 16)
mysql -e "CREATE DATABASE wings_ensayo_t82 CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci; CREATE USER 'ensayo_t82'@'localhost' IDENTIFIED BY '$PASS'; GRANT ALL ON wings_ensayo_t82.* TO 'ensayo_t82'@'localhost';" || exit 22
mysql wings_ensayo_t82 < /root/control-t82/extraido/wings.sql || exit 23
python3 /root/control-t82/auditar-datos.py compare wingstest wings_ensayo_t82
echo "RESULTADO_COMPARACION_COMPLETA $?"
COMMIT=$(git -c safe.directory=/home/wingstest/app -C /home/wingstest/app rev-parse HEAD)
echo "CODIGO_RESTAURADO $COMMIT"
GIT_TERMINAL_PROMPT=0 git clone -q https://github.com/cafrecio/Gestion_Wings.git /root/control-t82/app || exit 24
git -C /root/control-t82/app checkout -q "$COMMIT" || exit 25
cp /root/control-t82/extraido/env.txt /root/control-t82/app/.env
sed -i -e "s/^DB_DATABASE=.*/DB_DATABASE=wings_ensayo_t82/" -e "s/^DB_USERNAME=.*/DB_USERNAME=ensayo_t82/" -e "s/^DB_PASSWORD=.*/DB_PASSWORD=$PASS/" -e "s#^APP_URL=.*#APP_URL=http://127.0.0.1:8099#" /root/control-t82/app/.env
tar -xzf /root/control-t82/extraido/storage.tgz -C /root/control-t82/app || exit 26
python3 /root/control-t82/auditar-datos.py files /home/wingstest/app/storage/app /root/control-t82/app/storage/app || exit 27
cd /root/control-t82/app
COMPOSER_ALLOW_SUPERUSER=1 php82 /usr/local/bin/composer install -q --no-dev --optimize-autoloader --no-interaction || exit 28
npm ci --silent >/dev/null 2>&1 && npm run build >/dev/null 2>&1 || exit 29
mkdir -p storage/framework/{cache,sessions,views} storage/logs bootstrap/cache
php82 artisan config:clear -q
printf %s  | base64 -d > /root/control-t82/funcionamiento.php
FUENTE_CONTROL=wingstest php82 /root/control-t82/funcionamiento.php
FRC=$?
echo "RESULTADO_FUNCIONAL $FRC"
cd /root
exit "$FRC"
